        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "De ki: \"Allah'a ve Peygambere itaat edin\". Yüz çevirirlerse bilsinler ki, Allah inkar edenleri sevmez"
        }
