        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Şüphesiz bu anlatılanlar gerçek olaylardır. Allah'tan başka tanrı yoktur. Doğrusu Allah güçlüdür, Hakim'dir"
        }
