    "declic_frequence": "iʿtaṣama (s'attacher fortement, se prémunir, racine ع-ص-م) donne le verset central de la sourate : waʿtaṣimū bi-ḥabli Llāhi jamīʿan wa-lā tafarraqū — « attachez-vous tous ensemble au cordon d'Allah et ne vous divisez pas » (v.103). Le ḥabl est la corde qu'on lance à qui se noie, le lien qui retient au bord du gouffre — et le verset le dit : « vous étiez au bord d'un abîme de feu et Il vous en a sauvés ». La racine ع-ص-م dit la préservation : ce qui tient bon quand tout lâche. L'unité des croyants n'est pas un supplément d'âme mais une corde de survie — se diviser, c'est lâcher la corde au-dessus du vide."
